const fs = require('fs');
const data = $env.BRIEF_DATA_DIR || '/data';
const { execution, trigger, workflow } = $json;
const handled = execution?.error?.message === 'BRIEF_PROVIDER_UNAVAILABLE';
const run_id = execution?.id ? String(execution.id) : null;
const timestamp = new Date().toISOString();
const failure = {
  timestamp, run_id, workflow_id: workflow?.id ?? null, status: 'error',
  error_code: handled ? 'provider_unavailable' : 'workflow_failure',
  stage: execution?.lastNodeExecuted ?? (trigger ? 'trigger' : null),
};
fs.appendFileSync(data + '/errors.jsonl', JSON.stringify(failure) + '\n', { mode: 0o600 });

if (!handled) {
  // n8n may omit execution.id when execution saving is disabled or a trigger fails.
  // For unexpected failures, avoid a second terminal row if the run was already recorded.
  const path = data + '/runs.jsonl';
  const recorded = run_id && fs.existsSync(path) &&
    fs.readFileSync(path, 'utf8').split('\n').some(line => {
      try { return JSON.parse(line).run_id === run_id; } catch { return false; }
    });
  if (!recorded) {
    const duration = Number(execution?.executionTime);
    fs.appendFileSync(path, JSON.stringify({
      timestamp, run_id, input_summary: null, status: 'error',
      checks: [{ stage: 'workflow', passed: false }], generation_attempts: null,
      duration_ms: Number.isFinite(duration) ? duration : null,
    }) + '\n', { mode: 0o600 });
  }
}
return { json: failure };
